106 using TypeInfoRef = std::reference_wrapper<const std::type_info>;
107 
108 struct Hasher
109 {
110     std::size_t operator()(TypeInfoRef code) const
111     {
112         return code.get().hash_code();
113     }
114 };
115 
116 struct EqualTo
117 {
118     bool operator()(TypeInfoRef lhs, TypeInfoRef rhs) const
119     {
120         return lhs.get() == rhs.get();
121     }
122 };
